/**
 * Data-integrity checks for data/seed-statutes.json.
 *
 * The statutes seed is regenerated by scripts and merged from multiple sources
 * (NCRB Sankalan, civictech IPC dataset). A future re-scrape or merge could
 * silently reintroduce placeholder text, empty text, or drop letter sections
 * like 498A. These checks fail loudly (listing the offending sections) before
 * bad data ever reaches the database.
 *
 * The validation logic lives in src/lib/statutesIntegrity.ts and is shared
 * with the seeder pre-flight (src/seed-statutes.ts) so they can't drift.
 *
 * Run standalone via: pnpm --filter @workspace/api-server run check:statutes
 */
import { describe, it, expect } from "vitest";
import seedStatutes from "../../data/seed-statutes.json";
import {
  type StatuteSeedRow,
  checkTotalCount,
  checkPerCodeCounts,
  checkDuplicates,
  checkShortText,
  checkEmptyHeadings,
  checkPlaceholderText,
  checkIpcRepealText,
  checkKeyIpcSections,
  validateStatutesSeed,
} from "../lib/statutesIntegrity";

const rows = seedStatutes as unknown as StatuteSeedRow[];

function expectClean(result: { name: string; errors: string[] }) {
  expect(result.errors, `${result.name}: ${result.errors.join(", ")}`).toEqual([]);
}

describe("seed-statutes.json integrity", () => {
  it("has exactly the expected total row count", () => {
    expectClean(checkTotalCount(rows));
  });

  it("has the expected per-code row counts", () => {
    expectClean(checkPerCodeCounts(rows));
  });

  it("has no duplicate (code, section) pairs", () => {
    expectClean(checkDuplicates(rows));
  });

  it("has no empty or very short section text", () => {
    expectClean(checkShortText(rows));
  });

  it("has no empty headings", () => {
    expectClean(checkEmptyHeadings(rows));
  });

  it("contains no placeholder text in any row", () => {
    expectClean(checkPlaceholderText(rows));
  });

  it("has no repeal-notice text standing in for real IPC section text", () => {
    expectClean(checkIpcRepealText(rows));
  });

  it("includes key IPC sections (letter and sub-section numbering intact)", () => {
    expectClean(checkKeyIpcSections(rows));
  });

  it("passes the full validateStatutesSeed pre-flight used by the seeder", () => {
    const failures = validateStatutesSeed(rows);
    expect(
      failures,
      failures.map((f) => `${f.name}: ${f.errors.join(", ")}`).join("; "),
    ).toEqual([]);
  });
});
